<script setup lang="ts">
import type { Category, PointDraft } from '@/api/tracking'
defineProps<{ modelValue: PointDraft; categories: Category[] }>()
const emit = defineEmits<{ 'update:modelValue': [PointDraft] }>()
function patch(model: PointDraft, value: Partial<PointDraft>) { emit('update:modelValue', { ...model, ...value }) }
</script>
<template><section class="wizard-form"><h2>基础定义</h2><label>业务场景<select :value="modelValue.category_id" @change="patch(modelValue,{category_id:Number(($event.target as HTMLSelectElement).value)})"><option value="0">请选择</option><option v-for="c in categories.filter(c=>c.level==='SCENE'&&c.active)" :key="c.id" :value="c.id">{{ c.name }}（{{ c.code }}）</option></select></label><label>点位编码<input :value="modelValue.code" placeholder="product_detail_view" @input="patch(modelValue,{code:($event.target as HTMLInputElement).value})"></label><label>点位名称<input :value="modelValue.name" @input="patch(modelValue,{name:($event.target as HTMLInputElement).value})"></label><label>行为类型<select :value="modelValue.behavior_type" @change="patch(modelValue,{behavior_type:($event.target as HTMLSelectElement).value as PointDraft['behavior_type']})"><option value="">请选择</option><option v-for="v in ['PAGE_VIEW','ELEMENT_EXPOSE','ELEMENT_CLICK','BUSINESS_ACTION','BUSINESS_RESULT','CUSTOM']" :key="v">{{ v }}</option></select></label><label>说明<textarea :value="modelValue.description" @input="patch(modelValue,{description:($event.target as HTMLTextAreaElement).value})" /></label></section></template>
